return [
  {
    json: {
      plataforma: 'Kalunga',
      termo: 'teclado logitech keyboard k120 c fio',
      url: 'https://www.kalunga.com.br/busca/1?q=teclado-logitech-keybord-k120-c-fio',
      baseUrl: 'https://www.kalunga.com.br',
      referer: 'https://www.kalunga.com.br/',
      webhookUrl: $env.OFERTAS_WEBHOOK_URL || 'http://localhost:3000/api/webhooks/ofertas',
      webhookToken: $env.WEBHOOK_SECRET || 'Bearer INFORE_MVP_TOKEN_2026',
      maxProdutos: 20
    }
  }
];

const html = String($json.data || $json.body || '');
const cfg = $('CONFIGURAR BUSCA').first().json;

function decode(value) {
  return String(value || '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripTags(value) {
  return decode(String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' '));
}

function absoluteUrl(url) {
  const raw = decode(url);
  if (!raw) return '';
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.indexOf('//') === 0) return 'https:' + raw;
  if (raw.indexOf('/') === 0) return cfg.baseUrl + raw;
  return raw;
}

function toNumber(value) {
  const clean = String(value || '').replace(/\./g, '').replace(',', '.').replace(/[^\d.-]/g, '');
  return Number(clean) || 0;
}

if (!html || html.length < 500 || /captcha|cloudflare|access denied|acesso negado/i.test(html)) {
  return [{ json: { ofertas: [] } }];
}

const priceRegex = /R\$\s*\d{1,3}(?:\.\d{3})*,\d{2}/g;
const linkRegex = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]{0,1800}?)<\/a>/gi;
const seen = {};
const ofertas = [];
let match;

while ((match = linkRegex.exec(html)) !== null && ofertas.length < Number(cfg.maxProdutos || 20)) {
  const href = match[1];
  const block = match[0] + ' ' + html.slice(linkRegex.lastIndex, linkRegex.lastIndex + 1800);
  const url = absoluteUrl(href).split('#')[0];

  if (!url || seen[url]) continue;
  if (!/kalunga\.com\.br/i.test(url)) continue;
  if (/\/busca|javascript:|mailto:|login|minha-conta|carrinho/i.test(url)) continue;

  const prices = block.match(priceRegex) || [];
  if (!prices.length) continue;

  const titleAttrMatch = block.match(/(?:title|aria-label)=["']([^"']{8,180})["']/i);
  const altAttrMatch = block.match(/alt=["']([^"']{8,180})["']/i);
  const imageMatch = block.match(/<img[^>]+(?:src|data-src|data-original)=["']([^"']+)["']/i);
  const titleAttr = titleAttrMatch ? titleAttrMatch[1] : '';
  const altAttr = altAttrMatch ? altAttrMatch[1] : '';
  const textTitle = stripTags(match[2]).slice(0, 180);
  const titulo = decode(titleAttr || altAttr || textTitle);
  const precoDesconto = toNumber(prices[0]);
  const precoOriginal = toNumber(prices[1] || prices[0]);

  if (!titulo || titulo.length < 8 || !precoDesconto) continue;

  seen[url] = true;
  ofertas.push({
    titulo: titulo,
    preco_original: precoOriginal,
    preco_desconto: precoDesconto,
    url_afiliado: url,
    imagem_url: absoluteUrl(imageMatch ? imageMatch[1] : ''),
    plataforma: cfg.plataforma
  });
}

return [{ json: { ofertas: ofertas, webhookUrl: cfg.webhookUrl, webhookToken: cfg.webhookToken } }];
